'use client';

import Link from 'next/link';
import { useEffect, useMemo, useState } from 'react';

type Tenant = { id: string; businessName: string; ownerName: string; trade: string; plan: string; status: string; voiceNumber?: string | null; serviceSuburbs?: string[] };
type OpsCall = { id: string; tenantId: string; business: string; customer: string; outcome: string; durationSeconds: number | null; confidence: number | null; needsHumanReview: boolean; startedAt: string };
type OpsJob = { id: string; tenantId: string; business: string; customer: string; title: string; suburb: string; status: string; urgency: string; createdAt: string };
type OpsQuote = { id: string; tenantId: string; business: string; status: string; total: number; updatedAt: string };
type Overview = { tenants: Tenant[]; calls: OpsCall[]; jobs: OpsJob[]; quotes: OpsQuote[]; events: { id: string; type: string; createdAt: string; tenantId?: string | null }[] };
type Tab = 'operations' | 'calls' | 'jobs' | 'quotes' | 'tenants' | 'setup' | 'system' | 'growth';

const demoOverview: Overview = {
  tenants: [
    { id: 'bob', businessName: "Bob's Handyman", ownerName: 'Bob Harris', trade: 'Handyman', plan: 'Founding', status: 'pilot', voiceNumber: '07 5551 2040', serviceSuburbs: ['Carrara', 'Burleigh Waters', 'Palm Beach'] },
    { id: 'coast', businessName: 'Coastline Electrical', ownerName: 'Mick Turner', trade: 'Electrician', plan: 'Growth', status: 'pilot', voiceNumber: '07 5551 2072', serviceSuburbs: ['Broadbeach', 'Robina', 'Miami'] },
    { id: 'flow', businessName: 'Flow Right Plumbing', ownerName: 'Sam Lee', trade: 'Plumber', plan: 'Starter', status: 'onboarding', voiceNumber: null, serviceSuburbs: ['Nerang', 'Carrara'] },
  ],
  calls: [
    { id: 'c1', tenantId: 'bob', business: "Bob's Handyman", customer: 'Sarah Mitchell', outcome: 'Job captured', durationSeconds: 194, confidence: 94, needsHumanReview: false, startedAt: '2 min ago' },
    { id: 'c2', tenantId: 'coast', business: 'Coastline Electrical', customer: 'Dan Cole', outcome: 'Urgent job captured', durationSeconds: 126, confidence: 88, needsHumanReview: true, startedAt: '11 min ago' },
    { id: 'c3', tenantId: 'bob', business: "Bob's Handyman", customer: 'James Ryan', outcome: 'Quote requested', durationSeconds: 241, confidence: 91, needsHumanReview: false, startedAt: '1 hr ago' },
  ],
  jobs: [
    { id: 'j1', tenantId: 'bob', business: "Bob's Handyman", customer: 'Sarah Mitchell', title: 'Burst flexi hose', suburb: 'Burleigh Waters', status: 'new', urgency: 'urgent', createdAt: '2 min ago' },
    { id: 'j2', tenantId: 'coast', business: 'Coastline Electrical', customer: 'Dan Cole', title: 'Power tripping', suburb: 'Robina', status: 'callback_due', urgency: 'urgent', createdAt: '11 min ago' },
    { id: 'j3', tenantId: 'bob', business: "Bob's Handyman", customer: 'James Ryan', title: 'Toilet not flushing', suburb: 'Miami', status: 'draft_quote', urgency: 'standard', createdAt: '1 hr ago' },
    { id: 'j4', tenantId: 'coast', business: 'Coastline Electrical', customer: 'Priya Shah', title: 'Outdoor light install', suburb: 'Broadbeach', status: 'quoted', urgency: 'flexible', createdAt: '3 hrs ago' },
  ],
  quotes: [
    { id: 'q1', tenantId: 'bob', business: "Bob's Handyman", status: 'draft', total: 25500, updatedAt: '7 min ago' },
    { id: 'q2', tenantId: 'coast', business: 'Coastline Electrical', status: 'sent', total: 49500, updatedAt: '42 min ago' },
    { id: 'q3', tenantId: 'bob', business: "Bob's Handyman", status: 'accepted', total: 18500, updatedAt: 'Yesterday' },
  ],
  events: [
    { id: 'e1', type: 'call.completed', createdAt: '2 min ago', tenantId: 'bob' },
    { id: 'e2', type: 'job.urgent_alerted', createdAt: '2 min ago', tenantId: 'bob' },
    { id: 'e3', type: 'quote.sent', createdAt: '42 min ago', tenantId: 'coast' },
    { id: 'e4', type: 'quote.accepted', createdAt: 'Yesterday', tenantId: 'bob' },
  ],
};

export function OperatorConsole({ accessToken = null, demo = false }: { accessToken?: string | null; demo?: boolean }) {
  const [overview, setOverview] = useState<Overview>(demo ? demoOverview : { tenants: [], calls: [], jobs: [], quotes: [], events: [] });
  const [tab, setTab] = useState<Tab>('operations');
  const [loading, setLoading] = useState(!demo);
  const [error, setError] = useState<string | null>(null);
  const [onboarding, setOnboarding] = useState(false);
  const [createdLink, setCreatedLink] = useState<string | null>(null);
  const [search, setSearch] = useState('');

  useEffect(() => {
    if (demo) return;
    async function load() {
      if (!accessToken) { setError('Operator access is required.'); setLoading(false); return; }
      const response = await fetch('/api/operator/overview', { headers: { authorization: `Bearer ${accessToken}` }, cache: 'no-store' });
      const data = await response.json() as { overview?: unknown; error?: { message?: string } };
      if (!response.ok || !data.overview) { setError(data.error?.message ?? 'The operator console could not be loaded.'); setLoading(false); return; }
      setOverview(normaliseOverview(data.overview)); window.history.replaceState(null, '', '/operator'); setLoading(false);
    }
    void load();
  }, [accessToken, demo]);

  useEffect(() => {
    if (demo || !accessToken) return;
    const type = tab === 'system' ? 'operator.audit_viewed' : tab === 'growth' ? 'operator.growth_plan_viewed' : 'operator.tab_viewed';
    void fetch('/api/operator/telemetry', { method: 'POST', headers: { authorization: `Bearer ${accessToken}`, 'content-type': 'application/json' }, body: JSON.stringify({ type, tab }) });
  }, [accessToken, demo, tab]);

  const filteredJobs = useMemo(() => overview.jobs.filter((job) => `${job.business} ${job.customer} ${job.title} ${job.suburb}`.toLowerCase().includes(search.toLowerCase())), [overview.jobs, search]);
  const urgent = overview.jobs.filter((job) => ['urgent', 'emergency'].includes(job.urgency)).length;
  const drafts = overview.quotes.filter((quote) => ['draft', 'awaiting_approval'].includes(quote.status)).length;
  const accepted = overview.quotes.filter((quote) => quote.status === 'accepted').reduce((sum, quote) => sum + quote.total, 0);

  async function createTenant(event: React.FormEvent<HTMLFormElement>) {
    event.preventDefault(); setError(null);
    const form = new FormData(event.currentTarget);
    const body = { businessName: form.get('businessName'), ownerName: form.get('ownerName'), ownerPhone: form.get('ownerPhone'), trade: form.get('trade'), serviceSuburbs: String(form.get('serviceSuburbs') ?? '').split(',').map((item) => item.trim()).filter(Boolean), gstRegistered: form.get('gstRegistered') === 'on', plan: form.get('plan'), priceItems: [{ name: 'Call-out & assessment', unit: 'job', rateExGstCents: Math.round(Number(form.get('callout') || 0) * 100) }] };
    if (demo) {
      const tenant: Tenant = { id: crypto.randomUUID(), businessName: String(body.businessName), ownerName: String(body.ownerName), trade: String(body.trade), plan: String(body.plan), status: 'onboarding', serviceSuburbs: body.serviceSuburbs };
      setOverview((current) => ({ ...current, tenants: [...current.tenants, tenant] })); setCreatedLink('/app/demo'); setOnboarding(false); return;
    }
    const response = await fetch('/api/operator/tenants', { method: 'POST', headers: { authorization: `Bearer ${accessToken}`, 'content-type': 'application/json' }, body: JSON.stringify(body) });
    const data = await response.json() as { tenant?: Tenant; workspaceUrl?: string; error?: { message?: string } };
    if (!response.ok || !data.tenant) { setError(data.error?.message ?? 'The business could not be added.'); return; }
    setOverview((current) => ({ ...current, tenants: [...current.tenants, data.tenant!] })); setCreatedLink(data.workspaceUrl ?? null); setOnboarding(false);
  }

  function recordSalesAcademyOpen() {
    if (demo) {
      const previous = Number(localStorage.getItem('tradierelay-sales-academy-opens') ?? '0');
      localStorage.setItem('tradierelay-sales-academy-opens', String(previous + 1));
      localStorage.setItem('tradierelay-sales-academy-last-opened', new Date().toISOString());
      return;
    }
    if (!accessToken) return;
    void fetch('/api/operator/telemetry', {
      method: 'POST',
      headers: { authorization: `Bearer ${accessToken}`, 'content-type': 'application/json' },
      body: JSON.stringify({ type: 'operator.sales_academy_opened', tab }),
      keepalive: true,
    });
  }

  if (loading) return <OperatorAccess title="Opening Relay Ops…" body="Loading tenant, job and quote status." />;
  if (error && !overview.tenants.length) return <OperatorAccess title="Operator access needed" body={error} />;

  return <main className="operator-shell"><aside className="operator-sidebar"><Link href="/" className="operator-brand">TradieRelay<span>OPS</span></Link><nav aria-label="Operator console">{([['operations','Operations'],['calls','Live calls'],['jobs','Jobs'],['quotes','Quotes'],['tenants','Tradies'],['setup','Setup & rules'],['system','How Relay works'],['growth','10 → 50 plan']] as [Tab,string][]).map(([id,label]) => <button type="button" key={id} className={tab === id ? 'is-active' : ''} onClick={() => setTab(id)}><span className="operator-nav-icon">{navIcon(id)}</span><span className="operator-nav-label">{label}</span>{id === 'jobs' && urgent > 0 && <b>{urgent}</b>}</button>)}</nav><div className="operator-user"><span>N</span><div><strong>Noah &amp; Jake</strong><small>Founder console</small></div></div></aside><section className="operator-main"><header><div><span>NOAH &amp; JAKE OPERATOR CONSOLE</span><h1>{tabLabel(tab)}</h1></div><div className="operator-header-actions"><a className="operator-academy-link" href="https://tradierelay-sales-academy.pages.dev/" target="_blank" rel="noopener noreferrer" onClick={recordSalesAcademyOpen}>Sales Academy ↗</a><Link className="operator-tradie-app-link" href="/app/demo">Open tradie app</Link><button type="button" onClick={() => setOnboarding(true)}>+ Add a tradie</button></div></header>{error && <p className="relay-form-error">{error}</p>}{createdLink && <div className="operator-success"><span>Workspace ready.</span><Link href={createdLink}>Open secure workspace</Link><button type="button" onClick={() => setCreatedLink(null)}>×</button></div>}{tab === 'operations' && <Operations overview={overview} urgent={urgent} drafts={drafts} accepted={accepted} onSeeAll={() => setTab('jobs')} />}{tab === 'calls' && <Calls overview={overview} />}{tab === 'jobs' && <Jobs jobs={filteredJobs} search={search} onSearch={setSearch} />}{tab === 'quotes' && <Quotes quotes={overview.quotes} />}{tab === 'tenants' && <Tenants tenants={overview.tenants} onAdd={() => setOnboarding(true)} onReview={() => setTab('setup')} />}{tab === 'setup' && <Setup tenants={overview.tenants} accessToken={accessToken} demo={demo} />}{tab === 'system' && <SystemGuide tenants={overview.tenants} />}{tab === 'growth' && <GrowthPlan accessToken={accessToken} demo={demo} />}</section>{onboarding && <Onboarding onClose={() => setOnboarding(false)} onSubmit={createTenant} />}</main>;
}

function Operations({ overview, urgent, drafts, accepted, onSeeAll }: { overview: Overview; urgent: number; drafts: number; accepted: number; onSeeAll: () => void }) { const connected = overview.tenants.filter((tenant) => tenant.voiceNumber).length; return <><div className="operator-metrics"><Metric label="Active pilot tradies" value={String(overview.tenants.filter((tenant) => tenant.status === 'pilot').length)} note={`${overview.tenants.length} total`} /><Metric label="Urgent jobs now" value={String(urgent)} note="Needs a human" alert={urgent > 0} /><Metric label="Drafts waiting" value={String(drafts)} note="Approval reminders on" /><Metric label="Accepted value" value={money(accepted)} note="This view" /></div><div className="operator-grid"><article className="operator-panel"><div className="operator-panel-head"><div><span>NEEDS ATTENTION</span><h2>Do these next</h2></div><button type="button" onClick={onSeeAll}>See all</button></div><div className="attention-list">{overview.jobs.filter((job) => ['urgent','emergency'].includes(job.urgency) || job.status === 'callback_due').map((job) => <div key={job.id}><span className="attention-dot" /><div><strong>{job.customer} · {job.business}</strong><span>{job.title} · {job.suburb}</span></div><b>{job.createdAt}</b></div>)}</div></article><article className="operator-panel"><div className="operator-panel-head"><div><span>SYSTEM READINESS</span><h2>Live configuration</h2></div><span className={connected === overview.tenants.length ? 'health-live' : 'health-setup'}>● {connected}/{overview.tenants.length} numbers</span></div><div className="health-list"><div><span>AI receptionist</span><b>{connected ? `${connected} tenant${connected === 1 ? '' : 's'} connected` : 'Provider setup needed'}</b></div><div><span>SMS delivery</span><b>Status callbacks recorded</b></div><div><span>Quote follow-up</span><b>State checked before send</b></div><div><span>Secure links</span><b>Hashed, scoped + expiring</b></div></div></article><article className="operator-panel operator-activity"><div className="operator-panel-head"><div><span>AUDIT TRAIL</span><h2>Recent activity</h2></div></div>{overview.events.slice(0, 6).map((event) => <div key={event.id}><span>{event.type.replaceAll('.', ' ')}</span><b>{event.createdAt}</b></div>)}</article></div></>; }
function Calls({ overview }: { overview: Overview }) { return <div className="operator-panel operator-table-panel"><div className="operator-panel-head"><div><span>VOICE INBOX</span><h2>Recent AI calls</h2></div><span className="health-live">● Delivery monitored</span></div><div className="operator-table operator-call-table"><div className="operator-table-head"><span>Caller</span><span>Business</span><span>Call result</span><span>Quality</span></div>{overview.calls.map((call) => <div key={call.id}><strong>{call.customer}<small>{call.startedAt}</small></strong><span>{call.business}</span><span>{call.outcome}<small>{call.durationSeconds === null ? 'Duration unknown' : `${Math.floor(call.durationSeconds / 60)}m ${call.durationSeconds % 60}s`}</small></span><b className={call.needsHumanReview ? 'is-alert' : ''}>{call.needsHumanReview ? 'Review' : call.confidence === null ? 'Complete' : `${call.confidence}% confidence`}</b></div>)}{overview.calls.length === 0 && <div className="operator-empty-row"><span>No calls have reached this workspace yet.</span></div>}</div><div className="operator-call-note"><strong>What happens on a live call</strong><span>AI disclosure → one question at a time → address and timing → urgency check → read-back → secure job record → SMS to the configured tradie. It never gives a final price.</span></div></div>; }
function Jobs({ jobs, search, onSearch }: { jobs: OpsJob[]; search: string; onSearch: (value: string) => void }) { return <div className="operator-panel operator-table-panel"><div className="operator-panel-head"><div><span>ALL TENANTS</span><h2>Captured jobs</h2></div><input aria-label="Search jobs" value={search} onChange={(event) => onSearch(event.target.value)} placeholder="Search jobs…" /></div><div className="operator-table jobs-table"><div className="operator-table-head"><span>Customer</span><span>Business</span><span>Job</span><span>Status</span></div>{jobs.map((job) => <div key={job.id}><strong>{job.customer}<small>{job.suburb}</small></strong><span>{job.business}</span><span>{job.title}</span><b className={['urgent','emergency'].includes(job.urgency) ? 'is-alert' : ''}>{job.status.replaceAll('_',' ')}</b></div>)}</div></div>; }
function Quotes({ quotes }: { quotes: OpsQuote[] }) { return <div className="operator-panel operator-table-panel"><div className="operator-panel-head"><div><span>HUMAN APPROVED</span><h2>Quote pipeline</h2></div></div><div className="quote-pipeline">{['draft','sent','accepted'].map((status) => <div key={status}><span>{status.toUpperCase()}</span><strong>{quotes.filter((quote) => status === 'draft' ? ['draft','awaiting_approval'].includes(quote.status) : quote.status === status).length}</strong><small>{money(quotes.filter((quote) => status === 'draft' ? ['draft','awaiting_approval'].includes(quote.status) : quote.status === status).reduce((sum, quote) => sum + quote.total, 0))}</small></div>)}</div><div className="operator-table"><div className="operator-table-head"><span>Business</span><span>Status</span><span>Value</span><span>Updated</span></div>{quotes.map((quote) => <div key={quote.id}><strong>{quote.business}</strong><span>{quote.status.replaceAll('_',' ')}</span><span>{money(quote.total)}</span><b>{quote.updatedAt}</b></div>)}</div></div>; }
function Tenants({ tenants, onAdd, onReview }: { tenants: Tenant[]; onAdd: () => void; onReview: () => void }) { return <div className="tenant-grid">{tenants.map((tenant) => <article className="tenant-card" key={tenant.id}><div><span>{tenant.trade.toUpperCase()}</span><b className={`tenant-status ${tenant.status}`}>{tenant.status}</b></div><h2>{tenant.businessName}</h2><p>{tenant.ownerName}</p><dl><div><dt>Relay number</dt><dd>{tenant.voiceNumber ?? 'Being connected'}</dd></div><div><dt>Service area</dt><dd>{tenant.serviceSuburbs?.join(', ') || 'Configured'}</dd></div><div><dt>Plan</dt><dd>{tenant.plan}</dd></div></dl><button type="button" onClick={onReview}>Review setup →</button></article>)}<button type="button" className="tenant-add" onClick={onAdd}><span>+</span><strong>Add a tradie</strong><small>Business, rules, service area and verified prices</small></button></div>; }

type SetupPanel = 'rules' | 'prices' | 'routing' | 'optimisation';
type PriceView = { id: string; name: string; unit: string; rateExGstCents: number; active: boolean };
type TenantConfig = { greetingName: string; notificationPhone: string; callRules: Record<string, unknown> };
const demoTenantConfig: TenantConfig = { greetingName: "Bob's Handyman", notificationPhone: '+61 412 345 678', callRules: { answerWhen: 'missed_or_after_hours', maxMinutes: 6, backupNotificationPhone: '+61 421 555 017', urgentNotifyBackup: true } };
function Setup({ tenants, accessToken, demo }: { tenants: Tenant[]; accessToken: string | null; demo: boolean }) {
  const [tenantId, setTenantId] = useState(tenants[0]?.id ?? ''); const [panel, setPanel] = useState<SetupPanel>('rules'); const [prices, setPrices] = useState<PriceView[]>([{ id: 'demo-callout', name: 'Call-out & assessment', unit: 'job', rateExGstCents: 10000, active: true }]); const [config, setConfig] = useState<TenantConfig>(demoTenantConfig); const [notice, setNotice] = useState<string | null>(null); const [loading, setLoading] = useState(false);
  const tenant = tenants.find((item) => item.id === tenantId) ?? tenants[0];
  useEffect(() => { if (!tenantId) return; if (demo) { queueMicrotask(() => setConfig({ ...demoTenantConfig, greetingName: tenants.find((item) => item.id === tenantId)?.businessName ?? demoTenantConfig.greetingName })); return; } let cancelled = false; async function load() { setLoading(true); const response = await fetch(`/api/operator/tenants/${tenantId}`, { headers: { authorization: `Bearer ${accessToken}` }, cache: 'no-store' }); const data = await response.json() as { prices?: PriceView[]; settings?: TenantConfig }; if (!cancelled) { setPrices(Array.isArray(data.prices) ? data.prices : []); if (data.settings) setConfig({ greetingName: data.settings.greetingName, notificationPhone: data.settings.notificationPhone, callRules: data.settings.callRules ?? {} }); setLoading(false); } } void load(); return () => { cancelled = true; }; }, [accessToken, demo, tenantId, tenants]);
  async function saveTenantSettings(body: Record<string, unknown>) { if (!tenant) return false; if (demo) return true; const response = await fetch(`/api/operator/tenants/${tenant.id}`, { method: 'PATCH', headers: { authorization: `Bearer ${accessToken}`, 'content-type': 'application/json' }, body: JSON.stringify(body) }); return response.ok; }
  async function saveSettings(event: React.FormEvent<HTMLFormElement>) { event.preventDefault(); if (!tenant) return; const form = new FormData(event.currentTarget); const callRules = { ...config.callRules, answerWhen: form.get('answerWhen'), discloseAi: true, discloseRecording: true, neverQuoteByPhone: true, maxMinutes: Number(form.get('maxMinutes') ?? 6), handoffAfterFailedClarifications: 2 }; const nextConfig = { ...config, greetingName: String(form.get('greetingName') ?? tenant.businessName), notificationPhone: String(form.get('notificationPhone') ?? config.notificationPhone), callRules }; const body = { ...nextConfig, serviceSuburbs: String(form.get('serviceSuburbs') ?? '').split(',').map((item) => item.trim()).filter(Boolean) }; if (!(await saveTenantSettings(body))) { setNotice('Could not save those settings.'); return; } setConfig(nextConfig); setNotice('Rules saved and added to the audit trail.'); }
  async function saveRouting(event: React.FormEvent<HTMLFormElement>) { event.preventDefault(); const form = new FormData(event.currentTarget); const notificationPhone = String(form.get('notificationPhone') ?? '').trim(); const callRules = { ...config.callRules, backupNotificationPhone: String(form.get('backupNotificationPhone') ?? '').trim(), urgentNotifyBackup: form.get('urgentNotifyBackup') === 'on' }; const nextConfig = { ...config, notificationPhone, callRules }; if (!(await saveTenantSettings(nextConfig))) { setNotice('Could not save those routing destinations.'); return; } setConfig(nextConfig); setNotice('Call routing saved. New alerts will use these destinations.'); }
  async function addPrice(event: React.FormEvent<HTMLFormElement>) { event.preventDefault(); if (!tenant) return; const form = new FormData(event.currentTarget); const input = { name: String(form.get('name') ?? ''), unit: String(form.get('unit') ?? 'job'), rateExGstCents: Math.round(Number(form.get('rate') ?? 0) * 100) }; let price: PriceView = { id: crypto.randomUUID(), ...input, active: true }; if (!demo) { const response = await fetch(`/api/operator/tenants/${tenant.id}/prices`, { method: 'POST', headers: { authorization: `Bearer ${accessToken}`, 'content-type': 'application/json' }, body: JSON.stringify(input) }); const data = await response.json() as { price?: PriceView }; if (!response.ok || !data.price) { setNotice('Could not add that price.'); return; } price = data.price; } setPrices((current) => [...current, price]); event.currentTarget.reset(); setNotice('Verified price added.'); }
  async function togglePrice(price: PriceView) { if (!tenant) return; const active = !price.active; if (!demo) await fetch(`/api/operator/tenants/${tenant.id}/prices/${price.id}`, { method: 'PATCH', headers: { authorization: `Bearer ${accessToken}`, 'content-type': 'application/json' }, body: JSON.stringify({ active }) }); setPrices((current) => current.map((item) => item.id === price.id ? { ...item, active } : item)); }
  if (!tenant) return <div className="operator-panel"><h2>Add a tradie before configuring rules.</h2></div>;
  return <><div className="setup-toolbar"><label><span>BUSINESS</span><select value={tenant.id} onChange={(event) => setTenantId(event.target.value)}>{tenants.map((item) => <option key={item.id} value={item.id}>{item.businessName}</option>)}</select></label><span>{loading ? 'Loading setup…' : `${tenant.trade} · ${tenant.status}`}</span></div><div className="setup-grid">{([['rules','1','Answering rules','Greeting, service area and phone boundaries'],['prices','2','Verified price lists','Only human-approved amounts can prefill'],['routing','3','Call routing','Primary, urgent-copy and failed-delivery fallback'],['optimisation','4','Fortnightly optimisation','Failures, outcomes and rule changes']] as [SetupPanel,string,string,string][]).map(([id,number,title,copy]) => <button type="button" key={id} className={panel === id ? 'is-active' : ''} onClick={() => { setPanel(id); setNotice(null); }}><span>{number}</span><div><strong>{title}</strong><small>{copy}</small></div></button>)}</div>{notice && <div className="operator-success"><span>{notice}</span><button type="button" onClick={() => setNotice(null)}>×</button></div>}<article className="setup-editor operator-panel">{panel === 'rules' && <form key={`${tenant.id}-${config.greetingName}-${config.notificationPhone}`} onSubmit={saveSettings}><div className="operator-panel-head"><div><span>LIVE TENANT RULES</span><h2>What Relay may do on a call</h2></div></div><div className="operator-form-grid"><label><span>Greeting name</span><input name="greetingName" defaultValue={config.greetingName || tenant.businessName} /></label><label><span>Answer calls</span><select name="answerWhen" defaultValue={String(config.callRules.answerWhen ?? 'missed_or_after_hours')}><option value="missed_or_after_hours">Missed + after hours</option><option value="after_hours">After hours only</option><option value="all">Every call</option></select></label><label className="is-wide"><span>Service suburbs</span><input name="serviceSuburbs" defaultValue={tenant.serviceSuburbs?.join(', ')} /></label><label><span>Max call minutes</span><input name="maxMinutes" type="number" min="2" max="10" defaultValue={Number(config.callRules.maxMinutes ?? 6)} /></label><label><span>Hot lead mobile</span><input name="notificationPhone" defaultValue={config.notificationPhone} placeholder="+61 4…" /></label></div><div className="setup-safeguards"><span>✓ AI disclosure always on</span><span>✓ Never quote by phone</span><span>✓ Safety escalation always on</span></div><button className="customer-primary" type="submit">Save answering rules</button></form>}{panel === 'prices' && <><div className="operator-panel-head"><div><span>VERIFIED BY A HUMAN</span><h2>Quote starter prices</h2></div></div><div className="price-list">{prices.map((price) => <div key={price.id}><div><strong>{price.name}</strong><span>{money(price.rateExGstCents)} ex GST · per {price.unit}</span></div><button type="button" className={price.active ? 'is-active' : ''} onClick={() => void togglePrice(price)}>{price.active ? 'Active' : 'Paused'}</button></div>)}</div><form className="price-add" onSubmit={addPrice}><input name="name" required placeholder="Price item" /><select name="unit"><option value="job">job</option><option value="hour">hour</option><option value="item">item</option></select><input name="rate" required type="number" min="0" step="1" placeholder="$ ex GST" /><button type="submit">Add verified price</button></form></>}{panel === 'routing' && <form className="routing-form" key={`${tenant.id}-${config.notificationPhone}-${String(config.callRules.backupNotificationPhone ?? '')}`} onSubmit={saveRouting}><div className="operator-panel-head"><div><span>LIVE ALERT ROUTING</span><h2>Who receives a captured job</h2></div></div><p>Every lead goes to the primary mobile. Urgent jobs can copy a second person. If primary SMS delivery fails, Relay tries the backup and records the failure.</p><div className="operator-form-grid"><label><span>Primary hot-lead mobile</span><input name="notificationPhone" required defaultValue={config.notificationPhone} placeholder="+61 4…" /></label><label><span>Backup / overflow mobile</span><input name="backupNotificationPhone" defaultValue={String(config.callRules.backupNotificationPhone ?? '')} placeholder="+61 4…" /></label><label className="operator-checkbox is-wide"><input name="urgentNotifyBackup" type="checkbox" defaultChecked={config.callRules.urgentNotifyBackup === true} /><span>Send urgent and emergency leads to both mobiles</span></label></div><div className="routing-preview"><div><span>STANDARD LEAD</span><strong>Primary only</strong></div><div><span>URGENT LEAD</span><strong>{config.callRules.urgentNotifyBackup === true ? 'Primary + backup' : 'Primary only'}</strong></div><div><span>PRIMARY DELIVERY FAILS</span><strong>Backup + operator flag</strong></div></div><button className="customer-primary" type="submit">Save call routing</button></form>}{panel === 'optimisation' && <div className="setup-copy"><span className="customer-success-icon">14</span><h2>Review one fortnight at a time.</h2><p>Check completed briefs, unknown fields, human corrections, urgent alerts, draft age, quote acceptance and opt-outs. Change one rule at a time so the result is measurable.</p><button type="button" onClick={() => setNotice('Review note opened. Next review: 12 September 2026.')}>Start the next review note</button></div>}</article></>;
}

type SystemPanel = 'routing' | 'followup' | 'architecture' | 'setup';
function SystemGuide({ tenants }: { tenants: Tenant[] }) {
  const [panel, setPanel] = useState<SystemPanel>('routing');
  const connected = tenants.filter((tenant) => tenant.voiceNumber).length;
  return <div className="system-guide">
    <section className="operator-panel system-intro"><div><span>SERVICE PLAYBOOK</span><h2>Know exactly what happens—and what to configure.</h2><p>This is the operating manual Noah can sell from and Jake can build from. “Live” means the software path exists. “Customer setup” means it must be configured and tested for each tradie.</p></div><div className="system-readiness"><strong>{connected}/{tenants.length}</strong><span>demo tradies have a Relay number</span></div></section>
    <nav className="system-tabs" aria-label="System guide sections">{([['routing','Call routing'],['followup','Intelligent quote follow-up'],['architecture','Technical architecture'],['setup','Customer setup']] as [SystemPanel,string][]).map(([id,label]) => <button type="button" key={id} className={panel === id ? 'is-active' : ''} onClick={() => setPanel(id)}>{label}</button>)}</nav>
    {panel === 'routing' && <CallRoutingGuide />}
    {panel === 'followup' && <FollowUpGuide />}
    {panel === 'architecture' && <ArchitectureGuide />}
    {panel === 'setup' && <CustomerSetupGuide tenants={tenants} />}
  </div>;
}

function CallRoutingGuide() {
  const steps = [
    ['1', 'Customer rings the tradie', 'The tradie keeps their normal business number. Nothing changes for the caller.'],
    ['2', 'The carrier applies the rule', 'No answer, busy or after-hours calls are diverted to that customer’s dedicated Relay number.'],
    ['3', 'Relay matches the business', 'The number called identifies the tenant, greeting, trade, suburbs, urgency words and notification rules.'],
    ['4', 'The AI receptionist answers', 'It discloses that it is AI and that the call may be recorded, then asks one plain question at a time.'],
    ['5', 'Safety and urgency are checked', 'Danger language is escalated. The AI does not diagnose, promise attendance or give a final price.'],
    ['6', 'A secure job brief is created', 'Caller, job, suburb, timing, transcript confidence and photo link are attached to the right account.'],
    ['7', 'The configured people are alerted', 'The primary mobile gets every lead. An urgent-copy mobile can get urgent jobs and becomes the fallback if primary delivery fails.'],
  ];
  return <><div className="routing-flow">{steps.map(([number,title,copy]) => <article key={number}><span>{number}</span><div><strong>{title}</strong><p>{copy}</p></div></article>)}</div><div className="system-two-col"><article className="operator-panel"><div className="operator-panel-head"><div><span>ROUTING DECISION</span><h2>Which path handles the call?</h2></div></div><div className="decision-list"><div><b>Tradie answers</b><span>Relay does nothing.</span></div><div><b>Missed or after hours</b><span>AI receptionist captures the enquiry.</span></div><div><b>Voice service unavailable</b><span>Message mode records name, number and job.</span></div><div><b>Conversation drops</b><span>The caller is asked to leave a recorded message.</span></div><div><b>Immediate danger</b><span>Safety wording takes priority; the job is marked for urgent human review.</span></div></div></article><article className="operator-panel"><div className="operator-panel-head"><div><span>ROUTING CONTROLS</span><h2>What Jake configures per customer</h2></div></div><ul className="system-check-list"><li>Dedicated Relay voice and SMS numbers</li><li>Carrier diversion: no answer, busy and/or after hours</li><li>Primary hot-lead mobile</li><li>Urgent-copy and failed-delivery fallback mobile</li><li>Service suburbs, job types and urgency phrases</li><li>Maximum call length and message-mode fallback</li></ul></article></div></>;
}

function FollowUpGuide() {
  return <><div className="followup-timeline"><article><span>CALL ENDS</span><strong>Job brief and photo request</strong><p>The tradie gets the job link immediately. The customer gets a secure photo link if a mobile number was captured.</p></article><article><span>+4 HOURS</span><strong>Draft reminder</strong><p>If the quote is still a draft, Relay reminds the tradie. The customer sees nothing.</p></article><article><span>+24 HOURS</span><strong>Second draft check or customer nudge</strong><p>A draft gets one more tradie reminder. A sent or viewed quote gets one polite customer follow-up.</p></article><article><span>ANY RESPONSE</span><strong>The sequence stops</strong><p>Accepted quotes and change requests cancel scheduled customer follow-ups. STOP replies suppress later SMS.</p></article></div><div className="system-two-col"><article className="operator-panel"><div className="operator-panel-head"><div><span>WHY IT IS INTELLIGENT</span><h2>Status, not spam</h2></div></div><p className="system-copy">The follow-up worker checks the current quote state at send time. It only sends when the quote is still waiting, records delivery failures, respects opt-outs and never changes a price. The tradie remains the only person who can approve a quote.</p><div className="status-chips"><span>Draft → tradie only</span><span>Sent/viewed → customer</span><span>Accepted → stop</span><span>Change requested → stop + human</span></div></article><article className="operator-panel"><div className="operator-panel-head"><div><span>LIVE SCHEDULE</span><h2>Current pilot settings</h2></div></div><dl className="architecture-list"><div><dt>Draft reminder 1</dt><dd>4 hours</dd></div><div><dt>Draft reminder 2</dt><dd>24 hours</dd></div><div><dt>Customer follow-up</dt><dd>24 hours after send</dd></div><div><dt>Quote link</dt><dd>21-day secure token</dd></div><div><dt>Quote validity</dt><dd>14 days</dd></div></dl></article></div></>;
}

function ArchitectureGuide() {
  const rows = [
    ['Phone network', 'Conditional call forwarding', 'Sends only the agreed missed/after-hours calls to Relay.', 'Customer setup'],
    ['Twilio voice', 'Dedicated number + signed webhooks', 'Receives the call and starts AI conversation or message mode.', 'Live'],
    ['Voice worker', 'ConversationRelay websocket', 'Runs the controlled conversation and returns the final transcript.', 'Provider setup'],
    ['AI extraction', 'Structured job record', 'Turns the transcript into caller, job, suburb, urgency, timing and confidence.', 'Live'],
    ['Cloudflare D1', 'Tenant-isolated records', 'Stores customers, calls, jobs, prices, quotes, messages, follow-ups and audit events.', 'Live'],
    ['Cloudflare R2', 'Private photo objects', 'Stores customer photos; the app streams them only through authorised job links.', 'Live'],
    ['Twilio SMS', 'Alerts + delivery callbacks', 'Sends hot leads, photo links, quote links and follow-ups, then records delivery status.', 'Provider setup'],
    ['Scheduled worker', 'Due follow-up queue', 'Checks status at send time and completes, cancels or records failures.', 'Scheduler setup'],
  ];
  return <><article className="operator-panel architecture-panel"><div className="operator-panel-head"><div><span>TECHNICAL ARCHITECTURE</span><h2>What runs where</h2></div><span className="health-live">No customer data in the browser URL</span></div><div className="architecture-table"><div><b>Layer</b><b>Component</b><b>Job</b><b>Status</b></div>{rows.map((row) => <div key={row[0]}><strong>{row[0]}</strong><span>{row[1]}</span><span>{row[2]}</span><em className={row[3] === 'Live' ? 'is-live' : ''}>{row[3]}</em></div>)}</div></article><div className="system-two-col"><article className="operator-panel"><div className="operator-panel-head"><div><span>SECURITY BOUNDARIES</span><h2>How accounts stay separate</h2></div></div><ul className="system-check-list"><li>Every job, quote, photo and product is filtered by tenant ID.</li><li>Customer and tradie links are random, hashed, scoped and expire.</li><li>Provider webhooks require Twilio signatures or an internal HMAC.</li><li>Photos remain private objects and are streamed after access checks.</li><li>Quote totals are recalculated on the server before sending.</li><li>Final price approval always requires a tradie checkbox.</li></ul></article><article className="operator-panel"><div className="operator-panel-head"><div><span>FAILURE HANDLING</span><h2>When something goes wrong</h2></div></div><div className="decision-list"><div><b>AI connection missing</b><span>Message mode records the enquiry.</span></div><div><b>Primary SMS fails</b><span>Backup is attempted and the failure is logged.</span></div><div><b>Low-confidence call</b><span>Operator console marks it for review.</span></div><div><b>Quote has a blank price</b><span>Server blocks approval.</span></div><div><b>Customer opts out</b><span>Future automated SMS is suppressed.</span></div></div></article></div></>;
}

function CustomerSetupGuide({ tenants }: { tenants: Tenant[] }) {
  return <><div className="tenant-readiness-grid">{tenants.map((tenant) => <article className="operator-panel" key={tenant.id}><div className="tenant-readiness-head"><div><span>{tenant.trade.toUpperCase()}</span><h2>{tenant.businessName}</h2></div><b className={tenant.voiceNumber ? 'is-ready' : ''}>{tenant.voiceNumber ? 'Relay number set' : 'Number needed'}</b></div><ol><li className="is-done">Business, owner and service area</li><li className={tenant.voiceNumber ? 'is-done' : ''}>Dedicated Relay number</li><li>Primary + backup alert mobiles</li><li>Carrier forwarding switched on</li><li>Standard, urgent and failure tests passed</li></ol></article>)}</div><article className="operator-panel launch-test-panel"><div className="operator-panel-head"><div><span>BEFORE A CUSTOMER GOES LIVE</span><h2>Run this exact acceptance test</h2></div></div><div className="launch-test-grid">{['Ring and let it divert','Say a normal job','Say an urgent job','Give an unclear suburb','Interrupt the AI','Let the voice service fail','Upload a customer photo','Create, edit and send a quote','Accept the quote','Reply STOP to an SMS'].map((test,index) => <div key={test}><span>{String(index + 1).padStart(2,'0')}</span><strong>{test}</strong></div>)}</div><p>Do not mark a tenant live until the job lands in the correct account, both routing destinations behave as configured, the quote loop closes and failures appear in Operations.</p></article></>;
}

